{
  "genere": "obiettivo",
  "titolo": "Aggiungere lo scatto e raffinare il movimento del custode",
  "consegna": "Completa il controller del Custode aggiungendo la possibilità di scattare (sprint) e garantendo che il movimento in 8 direzioni sia bilanciato.

1. Nelle Impostazioni del Progetto (Input Map), aggiungi una nuova azione di input chiamata `sprint` associata al tasto Shift (`Shift`).
2. In `res://player.gd`, dichiara la nuova proprietà esportata `@export var sprint_multiplier: float = 1.5`.
3. Modifica lo script `player.gd` per fare in modo che:
   - Quando l'azione `sprint` è premuta (`Input.is_action_pressed("sprint")`), la velocità massima bersaglio sia pari a `max_speed * sprint_multiplier`.
   - Quando l'azione `sprint` non è premuta, la velocità massima bersaglio sia `max_speed`.
   - Il calcolo della direzione tramite `get_input_direction()` continui a usare `Input.get_vector()`, in modo che muovendosi in diagonale la lunghezza della velocità massima rimanga pari alla velocità massima consentita (senza andare più veloci in obliquo).
   - L'accelerazione e la frenata graduali continuino ad applicarsi con `velocity.move_toward()`.",
  "modalita": "progetto",
  "dove": "gioco",
  "cartella": "il-custode",
  "passiGuida": [],
  "suggerimenti": [
    "Puoi aggiungere l'azione `sprint` aprendo *Project -> Project Settings -> Input Map*, scrivendo `sprint` e associando il tasto Shift."
  ],
  "verifiche": [
    {
      "tipo": "azione_input",
      "nome": "sprint",
      "descrizione": "L'azione di input sprint è stata configurata nella Input Map del progetto"
    },
    {
      "tipo": "testo_in_file",
      "percorso": "res://player.gd",
      "regex": "sprint_multiplier",
      "descrizione": "Lo script player.gd dichiara la proprietà sprint_multiplier"
    },
    {
      "tipo": "script_godot",
      "codice": "extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player_exists", player != null, "Il nodo Player deve essere un CharacterBody2D nella scena main.tscn"):
		return

	player.position = Vector2(400.0, 300.0)
	player.velocity = Vector2.ZERO

	var max_speed: float = get_prop(player, "max_speed", 200.0)
	var sprint_mult: float = get_prop(player, "sprint_multiplier", 1.5)

	Input.action_press("move_right")
	await wait_physics_frames(30)
	check("normal_speed", absf(player.velocity.x - max_speed) < 2.0, "Senza scatto la velocità massima orizzontale deve essere pari a max_speed (trovata velocity.x = %.1f, atteso %.1f)" % [player.velocity.x, max_speed])
	Input.action_release("move_right")

	await wait_physics_frames(25)
	check("brake_to_zero", player.velocity.length() < 1.0, "Rilasciando i tasti la velocità deve azzerarsi per la frenata (trovata velocità = %.1f)" % player.velocity.length())

	player.position = Vector2(400.0, 300.0)
	player.velocity = Vector2.ZERO
	Input.action_press("sprint")
	Input.action_press("move_right")
	await wait_physics_frames(30)
	var expected_sprint: float = max_speed * sprint_mult
	check("sprint_speed", absf(player.velocity.x - expected_sprint) < 3.0, "Con lo scatto attivo la velocità X deve raggiungere max_speed * sprint_multiplier (trovata velocity.x = %.1f, atteso %.1f)" % [player.velocity.x, expected_sprint])
	Input.action_release("sprint")
	Input.action_release("move_right")

	await wait_physics_frames(10)
	player.position = Vector2(400.0, 300.0)
	player.velocity = Vector2.ZERO
	Input.action_press("move_right")
	Input.action_press("move_down")
	await wait_physics_frames(35)
	var diag_speed: float = player.velocity.length()
	check("diagonal_speed", absf(diag_speed - max_speed) < 3.0, "In diagonale la lunghezza della velocità deve rimanere pari a max_speed (trovata velocità = %.1f, atteso %.1f)" % [diag_speed, max_speed])
	Input.action_release("move_right")
	Input.action_release("move_down")
",
      "descrizione": "Il custode risponde alle azioni di movimento con accelerazione, frenata, scatto con Shift e velocità diagonale normalizzata"
    }
  ],
  "soluzione": {
    "progetto": {
      "nome": "Il custode",
      "scenaPrincipale": "res://main.tscn",
      "azioni": [
        {
          "nome": "move_left",
          "tasti": [
            "A",
            "Left"
          ]
        },
        {
          "nome": "move_right",
          "tasti": [
            "D",
            "Right"
          ]
        },
        {
          "nome": "move_up",
          "tasti": [
            "W",
            "Up"
          ]
        },
        {
          "nome": "move_down",
          "tasti": [
            "S",
            "Down"
          ]
        },
        {
          "nome": "sprint",
          "tasti": [
            "Shift"
          ]
        }
      ],
      "autoload": [],
      "impostazioni": []
    },
    "file": [
      {
        "percorso": "guard.gd",
        "contenuto": "extends CharacterBody2D

@export var speed: float = 120.0
@export var acceleration: float = 800.0
@export var friction: float = 600.0
@export var target_position: Vector2 = Vector2.ZERO


func _physics_process(delta: float) -> void:
	var distance: float = global_position.distance_to(target_position)
	if distance > 4.0:
		var direction: Vector2 = global_position.direction_to(target_position)
		if direction != Vector2.ZERO:
			rotation = direction.angle()
		var target_velocity: Vector2 = direction * speed
		velocity = velocity.move_toward(target_velocity, acceleration * delta)
	else:
		velocity = velocity.move_toward(Vector2.ZERO, friction * delta)

	move_and_slide()
"
      },
      {
        "percorso": "main.tscn",
        "contenuto": "[gd_scene format=3]

[ext_resource type="Texture2D" path="res://icon.svg" id="1_icon"]
[ext_resource type="Script" path="res://player.gd" id="2_player"]
[ext_resource type="Script" path="res://guard.gd" id="3_guard"]

[node name="Main" type="Node2D"]

[node name="Player" type="CharacterBody2D" parent="."]
position = Vector2(200, 200)
script = ExtResource("2_player")

[node name="Sprite2D" type="Sprite2D" parent="Player"]
texture = ExtResource("1_icon")

[node name="Guard" type="CharacterBody2D" parent="."]
position = Vector2(100, 100)
script = ExtResource("3_guard")

[node name="Sprite2D" type="Sprite2D" parent="Guard"]
texture = ExtResource("1_icon")
"
      },
      {
        "percorso": "player.gd",
        "contenuto": "extends CharacterBody2D

@export var max_speed: float = 200.0
@export var acceleration: float = 1200.0
@export var friction: float = 1000.0
@export var sprint_multiplier: float = 1.5


func _physics_process(delta: float) -> void:
	var input_direction: Vector2 = get_input_direction()
	update_velocity(input_direction, delta)
	move_and_slide()


func get_input_direction() -> Vector2:
	return Input.get_vector("move_left", "move_right", "move_up", "move_down")


func update_velocity(direction: Vector2, delta: float) -> void:
	if direction != Vector2.ZERO:
		var current_max_speed: float = max_speed
		if Input.is_action_pressed("sprint"):
			current_max_speed *= sprint_multiplier
		var target_velocity: Vector2 = direction * current_max_speed
		velocity = velocity.move_toward(target_velocity, acceleration * delta)
	else:
		velocity = velocity.move_toward(Vector2.ZERO, friction * delta)
"
      }
    ],
    "spiegazione": "Abbiamo aggiunto l'azione di input `sprint` mappata sul tasto Shift e la proprietà `@export var sprint_multiplier: float = 1.5`. Nella funzione `update_velocity()`, verifichiamo se l'azione `sprint` è attualmente premuta tramite `Input.is_action_pressed("sprint")`: in tal caso, la velocità massima bersaglio diventa `max_speed * sprint_multiplier`. Poiché `get_input_direction()` usa `Input.get_vector()`, il vettore direzione ha sempre lunghezza 1.0 anche lungo le diagonali, evitando che il Custode superi la velocità consentita quando si muove in obliquo."
  }
}
